<?php require __DIR__.'/../db.php'; $db=connect_db($config['db']); ensure_core_tables($db); $students=$db->query('SELECT id,full_name FROM students ORDER BY full_name')->fetchAll()?:[]; $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $amt=(float)$_POST['amount']; $paid=(float)$_POST['paid_amount']; $status=$paid>=$amt?'Paid':'Pending'; $st=$db->prepare('INSERT INTO fees(student_id,month_key,amount,paid_amount,status) VALUES(:sid,:m,:a,:p,:s)'); $st->execute(['sid'=>(int)$_POST['student_id'],'m'=>trim($_POST['month_key']),'a'=>$amt,'p'=>$paid,'s'=>$status]); $msg='Fee collected'; } include __DIR__.'/../layout/header.php'; include __DIR__.'/../layout/sidebar.php'; ?>
<h3>Fee Collect</h3><p class="text-success"><?= h($msg) ?></p><form method="post" class="row g-2"><div class="col-md-3"><select class="form-control" name="student_id"><?php foreach($students as $s): ?><option value="<?= (int)$s['id'] ?>"><?= h((string)$s['full_name']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><input class="form-control" name="month_key" placeholder="2026-03"></div><div class="col-md-2"><input class="form-control" name="amount" placeholder="Amount"></div><div class="col-md-2"><input class="form-control" name="paid_amount" placeholder="Paid"></div><div class="col-md-2"><button class="btn btn-primary">Save</button></div></form>
<?php include __DIR__.'/../layout/footer.php'; ?>
